    const logger = overrides.logger ?? silentLogger;
    const clock = overrides.clock ?? { now: () => new Date() };
    const ids = overrides.ids ?? new UlidIds(clock);
    if (!config.dbUrl.startsWith(':memory:') && !config.dbUrl.includes('mode=memory')) {
