import type { FastifyBaseLogger } from 'fastify';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HarnessId, LoopDefinitionInput } from '@graphgoblin/contracts';
import type { HarnessPort } from '@graphgoblin/engine';
import type { StorageCapacityPort } from '@graphgoblin/infrastructure/fs';
import {
  CapturingLogger,
  FakeClock,
  FakeDecider,
  FakeClassifier,
  FakeClassifierRegistry,
  FakeHarness,
  FakeStructured,
} from '@graphgoblin/engine/testing';
import { buildApp } from '../app.js';
import { loadConfig } from '../config.js';
import { createContainer, type Container } from '../container.js';
import type { ApiInstance } from '../types.js';
export {
  startFakeClassifierEndpoint,
  type FakeClassifierRequest,
  type FakeClassifierResponse,
} from './fake-classifier.js';

export interface TestApp {
  app: ApiInstance;
  container: Container;
  harness: FakeHarness;
  jev: FakeClassifier;
  codex: FakeDecider;
  structured: FakeStructured;
  logger: CapturingLogger;
  clock: FakeClock;
  dataDir: string;
  /** Create a loop from a definition and publish it; returns the loop id. */
  publishLoop(definition: LoopDefinitionInput, headers?: Record<string, string>): Promise<string>;
  idle(): Promise<void>;
  close(): Promise<void>;
}

export interface TestAppOptions {
  storageCapacity?: StorageCapacityPort;
  /** Distinguish disposable history-deletion fixtures from other API test data. */
  tempPrefix?: string;
  clock?: FakeClock;
  harnesses?: Partial<Record<HarnessId, HarnessPort>>;
  requireApiKey?: boolean;
  env?: Record<string, string>;
  /** Exercise real catalog/secret resolution and HTTP transport, retaining fake Codex. */
  realClassifiers?: boolean;
  /**
   * A real server logger for both the container and HTTP, as `serve()` composes them. The
   * returned capturing `logger` then records nothing.
   */
  serverLogger?: FastifyBaseLogger;
}

/** An API over an in-memory database with fake harness, deciders, and structured completion. */
export async function createTestApp(options: TestAppOptions = {}): Promise<TestApp> {
  const dataDir = await mkdtemp(
    join(tmpdir(), options.tempPrefix ?? process.env['GG_TEST_DATA_PREFIX'] ?? 'gg-api-'),
  );
  const config = loadConfig({
    GG_DATA_DIR: dataDir,
    GG_DB_URL: ':memory:',
    GG_SWAGGER_UI: 'false',
    GG_REQUIRE_API_KEY: options.requireApiKey ? 'true' : 'false',
    GG_OLLAMA_ENABLED: 'false',
    GG_MASTER_KEY: Buffer.alloc(32, 9).toString('base64'),
    ...options.env,
  });
  const harness = new FakeHarness();
  const jev = new FakeClassifier('jev');
  const codex = new FakeDecider('codex');
  const structured = new FakeStructured();
  const logger = new CapturingLogger();
  const clock = options.clock ?? new FakeClock();
  const container = await createContainer(config, {
    storageCapacity: options.storageCapacity ?? {
