import { z } from 'zod';
import { DecisionConfigSchema } from './evaluation.js';
export { DecisionConfigSchema, type DecisionConfig } from './evaluation.js';
import {
  EffortSchema,
  ExpressionSchema,
  HarnessIdSchema,
  ModelNameSchema,
  JsonSchemaSchema,
  RepairPolicySchema,
  SlugSchema,
  TemplateSchema,
  TimestampSchema,
  UlidSchema,
} from './common.js';
import { field } from './meta.js';
import { CodexConfigOverridesSchema } from './codex-config.js';
import {
  CollectionSelectionSchema,
  InjectedMessageSchema,
  MessageSelectionSchema,
  MutationListSchema,
} from './mutations.js';
import { ReturnChannelSchema } from './thread.js';
import { PollItemsSchema, WebhookConfigSchema } from './trigger-integrations.js';

export const NodeKindSchema = z.enum([
  'trigger',
  'decision',
  'inference',
  'script',
  'mutate',
  'subloop',
  'wait',
  'heartbeat',
  'exit',
]);
export type NodeKind = z.infer<typeof NodeKindSchema>;

/** Which surfaces may start or wake a node. */
export const ExposeToSchema = z
  .array(z.enum(['ui', 'api', 'mcp']))
  .min(1)
  .default(['ui', 'api', 'mcp']);

const RouteLabelSchema = SlugSchema.refine((s) => s !== 'in', 'a route may not be named "in"');


export const ProbeSchema = z.discriminatedUnion('kind', [
  z.strictObject({
    kind: z.literal('http'),
    method: z.enum(['GET', 'POST', 'HEAD']).default('GET'),
    url: TemplateSchema,
    headers: z.record(z.string(), TemplateSchema).optional(),
    body: TemplateSchema.optional(),
    timeoutSeconds: z.number().int().positive().max(300).default(30),
  }),
  z.strictObject({
    kind: z.literal('script'),
    command: z.string().min(1),
    args: z.array(TemplateSchema).default([]),
    timeoutSeconds: z.number().int().positive().max(3600).default(60),
  }),
  z.strictObject({ kind: z.literal('signal-count'), name: SlugSchema }),
  z.strictObject({ kind: z.literal('none') }),
]);
export type Probe = z.infer<typeof ProbeSchema>;


const DedupeKeySchema = ExpressionSchema.optional().meta(
  field('JSONata producing a key; a repeated key does not start another run.'),
);

export const TriggerConfigSchema = z.union([
]);
export type SessionPolicy = z.infer<typeof SessionPolicySchema>;

export const HarnessOptionsSchema = z.strictObject({
  sandbox: z
    .enum(['read-only', 'workspace-write', 'danger-full-access'])
    .default('workspace-write')
    .meta(
      field(
        'Sandbox or tool policy. Claude requires an explicit supported policy and provides no OS/read-path confinement.',
        { control: 'claude-policy' },
      ),
    ),
  approval: z
    .enum(['never', 'on-request'])
    .default('never')
    .meta(
      field('Whether the harness may stop to ask before acting.', {
        advanced: true,
        control: 'claude-approval',
      }),
    ),
  networkAccess: z
    .boolean()
    .optional()
    .meta(field('Let commands in the sandbox reach the network.', { advanced: true })),
  webSearch: z
    .boolean()
    .optional()
    .meta(field('Let the model search the web.', { advanced: true })),
  configOverrides: CodexConfigOverridesSchema.optional().meta(
    field(
      'Raw Codex configuration. Each dotted key segment must use letters, digits, _ or -, and not __proto__, constructor or prototype.',
      {
        advanced: true,
        jsonEditor: true,
      },
    ),
  ),
});
export type HarnessOptions = z.infer<typeof HarnessOptionsSchema>;

export const CapabilitiesSchema = z.strictObject({
  mcpServers: z.array(SlugSchema.meta({ control: 'capability-mcpServers' })).optional(),
  plugins: z.array(SlugSchema.meta({ control: 'capability-plugins' })).optional(),
  skills: z.array(SlugSchema.meta({ control: 'capability-skills' })).optional(),
});
export type Capabilities = z.infer<typeof CapabilitiesSchema>;

/** Static native Claude policy validation, shared by authored contracts and the adapter boundary. */
export function claudePolicyIssues(
  options: HarnessOptions,
  capabilities?: Capabilities,
): { path: string[]; message: string }[] {
  const issues: { path: string[]; message: string }[] = [];
  const add = (name: string, message: string) =>
    issues.push({ path: ['harnessOptions', name], message });
  if (options.approval !== 'never') add('approval', 'Claude on-request approval is unsupported');
  if (options.sandbox !== 'read-only' && options.sandbox !== 'danger-full-access')
    add(
      'sandbox',
      'Claude workspace-write cannot enforce the requested boundary; choose an explicit supported policy',
    );
  if (options.networkAccess === false)
    add('networkAccess', 'Claude command network isolation is unsupported');
  if (options.webSearch === true) add('webSearch', 'Claude web search is unsupported');
  if (options.configOverrides && Object.keys(options.configOverrides).length)
    add('configOverrides', 'Claude raw configuration overrides are unsupported');
  if (capabilities)
    for (const [name, values] of Object.entries(capabilities))
      if (values?.length)
        issues.push({
          path: ['capabilities', name],
          message: 'Claude custom capabilities are unsupported',
        });
  return issues;
}

/** Ollama v1 is a fresh, tool-free text turn; labels do not claim OS confinement. */
export function ollamaPolicyIssues(config: {
  session: SessionPolicy;
  harnessOptions: HarnessOptions;
  capabilities?: Capabilities | undefined;
  contextFiles?: { path: string; template: string }[] | undefined;
  output: { schema?: { repair: { enabled: boolean } } | undefined };
}): { path: string[]; message: string }[] {
  const issues: { path: string[]; message: string }[] = [];
  const add = (path: string[], message: string) => issues.push({ path, message });
  if (config.session.policy !== 'fresh')
    add(['session', 'policy'], 'Ollama supports fresh sessions only');
  if (config.harnessOptions.sandbox !== 'read-only')
    add(['harnessOptions', 'sandbox'], 'Ollama requires the tool-free read-only policy');
  if (config.harnessOptions.approval !== 'never')
    add(['harnessOptions', 'approval'], 'Ollama does not support approval prompts');
  for (const name of ['webSearch', 'networkAccess'] as const)
    if (config.harnessOptions[name] === true)
      add(['harnessOptions', name], 'Ollama model tool access is unsupported');
  if (
    config.harnessOptions.configOverrides &&
    Object.keys(config.harnessOptions.configOverrides).length
  )
    add(
      ['harnessOptions', 'configOverrides'],
      'Ollama raw configuration overrides are unsupported',
    );
  if (config.contextFiles?.length)
    add(['contextFiles'], 'Ollama context files are unsupported; include text in the prompt');
  for (const [name, values] of Object.entries(config.capabilities ?? {}))
    if (values?.length) add(['capabilities', name], 'Ollama custom capabilities are unsupported');
  if (config.output.schema?.repair.enabled)
    add(
      ['output', 'schema', 'repair', 'enabled'],
      'Ollama same-session schema repair is unsupported',
    );
  return issues;
}

export const InferenceConfigSchema = z
  .strictObject({
    harness: HarnessIdSchema.default('codex').meta(field('Harness that runs the session.')),
    model: ModelNameSchema.optional().meta(
      field('Model; inherits within this harness from loop, owner, then process defaults.', {
        control: 'model',
      }),
    ),
    effort: EffortSchema.optional().meta(
      field(
        'Reasoning effort; inherits within this harness like the model. Catalog effort is guidance only.',
        {
          control: 'effort',
        },
      ),
    ),
    // Context is the editor's presentation only; the editor shows prompt before session.
    session: SessionPolicySchema.default({ policy: 'fresh' }).meta(
      field(
        'Choose whether each visit starts a new conversation or resumes an existing one. Prompt, input and context files determine the information supplied for the visit.',
        { context: true },
      ),
    ),
    prompt: z
      .strictObject({ template: TemplateSchema })
      .meta(field('Liquid template rendered against the thread.', { context: true })),
    input: MutationListSchema.default([]).meta(
      field('Mutations applied to the thread view the template sees.', {
        context: true,
        jsonEditor: true,
      }),
    ),
    contextFiles: z
      .array(z.strictObject({ path: z.string().min(1).max(1024), template: TemplateSchema }))
      .max(32)
      .optional()
      .meta(
        field('Files written under the working directory before the session starts.', {
          advanced: true,
          context: true,
          group: 'Files',
          jsonEditor: true,
        }),
      ),
    harnessOptions: HarnessOptionsSchema.prefault({}).meta(
      field('Sandbox, approval, network, web search, and raw config overrides.', {
        group: 'Harness options',
      }),
    ),
    capabilities: CapabilitiesSchema.optional().meta(
      field(
        'MCP server, plugin, and skill slugs are recorded but not yet resolved; use raw harness config overrides to configure tools.',
        {
          advanced: true,
          group: 'Harness options',
          jsonEditor: true,
        },
      ),
    ),
    output: z
      .strictObject({
        capture: z
          .enum(['auto', 'text'])
          .optional()
          .meta(
            field(
              'Omitted or auto uses existing JSON-or-text capture; text captures final text verbatim.',
              { advanced: true },
            ),
          ),
        captureTranscript: z
          .enum(['artifact', 'none'])
          .default('artifact')
          .meta(field('Keep the session transcript as an artifact, or not.', { advanced: true })),
        toMessages: z
          .enum(['final', 'final-and-notes', 'none'])
          .default('final')
          .meta(field("What the answer adds to the thread's messages.", { advanced: true })),
        transforms: MutationListSchema.default([]).meta(
          field('Mutations applied to the answer before it lands.', {
            advanced: true,
            jsonEditor: true,
          }),
        ),
        schema: z
          .strictObject({
            jsonSchema: JsonSchemaSchema,
            native: z.boolean().default(true),
            repair: RepairPolicySchema.prefault({}),
          })
          .optional()
          .meta(
            field('JSON Schema the answer must satisfy, with repair turns when it does not.', {
              advanced: true,
            }),
          ),
      })
      .prefault({})
      .meta(
        field(
          'Transcript capture, how the answer lands in messages, transforms, and an optional output schema with repair.',
          { advanced: true, group: 'Output' },
        ),
      ),
    timeoutSeconds: z
      .number()
      .int()
      .positive()
      .max(86_400)
      .optional()
      .meta(
        field('Optional watchdog; a timeout fails the run.', { advanced: true, group: 'Limits' }),
      ),
  })
  .superRefine((config, ctx) => {
    if (config.output.capture === 'text' && config.output.schema)
      ctx.addIssue({
        code: 'custom',
        path: ['output', 'schema'],
        message: 'Text capture cannot also require a structured output schema',
      });
    if (config.harness === 'ollama')
      for (const issue of ollamaPolicyIssues(config)) ctx.addIssue({ code: 'custom', ...issue });
    if (config.harness === 'claude')
      for (const issue of claudePolicyIssues(config.harnessOptions, config.capabilities))
        ctx.addIssue({ code: 'custom', ...issue });
  });
export type InferenceConfig = z.infer<typeof InferenceConfigSchema>;

// ---------------------------------------------------------------------------
// Script
// ---------------------------------------------------------------------------

export const ScriptConfigSchema = z
  .strictObject({
    command: z.string().min(1).max(4096).meta(field('Program to run.')),
    args: z
      .array(TemplateSchema)
      .max(256)
      .default([])
      .meta(field('Arguments; each may be a Liquid template.')),
    cwd: z
      .string()
      .min(1)
      .max(4096)
      .default('workspace')
      .meta(field('`workspace` for the run working directory, or a path.')),
    env: z
      .record(z.string(), z.string().max(8192))
