export const WorkingDirectorySpecSchema = z.discriminatedUnion('kind', [
  z.strictObject({ kind: z.literal('fixed'), path: z.string().min(1).max(4096) }),
  z.strictObject({ kind: z.literal('template'), template: TemplateSchema }),
